def add(a, b):
    return a + b

print(add(3, 5))

def power(base, exp=2):
    return base ** exp

print(power(5))

def min_max(numbers):
    return min(numbers), max(numbers)

lo, hi = min_max([3, 1, 7, 2, 9])
print(lo, hi)

def repeat_print(text, times):
    for _ in range(times):
        print(text)

repeat_print('hello', 3)

